  if (!run('node', ['scripts/ops-monitoring.test.mjs'])) return false;
  if (!BASH) { console.error('bash 를 못 찾았습니다 (Git Bash 필요).'); return false; }
  return run(BASH, ['packages/db/scripts/admin-acl.test.sh']);
